from series import *
start('استاد دوستدار','doostdar',[('ساختار و سل','دیواره، ایمنی و شکل‌های بیماری'),('تشخیص و مقاومت سل','آزمون‌ها، واکسن و مفاهیم درمان'),('مایکوباکتری‌های دیگر و جذام','طبقه‌بندی، تظاهر و ایمنی'),('اسپیروکت‌ها','سیفلیس، بورلیا و لپتوسپیرا')])
A(1,'دیوارهٔ مایکوباکتری و اسیدفست',[3,4], 'دیوارهٔ چربی‌دار، رنگ‌پذیری و بقا را به هم وصل می‌کند.',[
 ['ویژگی پایه','باسیل، هوازی، بدون اسپور و حرکت؛ در متن گرم مثبت ولی رنگ‌آمیزی گرم معمول برای شناسایی مناسب نیست. بیشتر گونه‌ها کندرشدند، با استثناهای سریع‌تر.'],
 ['مایکولیک اسید و پپتیدوگلیکان','ساختار چربی‌دار و نفوذپذیری کم؛ با دشواری ورود رنگ و بعضی داروها مرتبط است.'],['سولفاتید و LAM','در روایت متن، اختلال ادغام فاگوزوم و لیزوزوم'],['فاکتور طنابی و مایکوزید','فاکتور طنابی، ترهالوز دی‌مایکولات؛ نقش در تعامل با فاگوسیت و بقا به مایکوزید هم نسبت داده شده است.'],['پروتئین و آنزیم','پروتئین شوک حرارتی و SOD؛ آنتی‌ژن‌های مرتبط با حساسیت تأخیری'],['اصل اسیدفست','حفظ رنگ اولیه در برابر رنگ‌بری اسیدی؛ باسیل قرمز در زمینهٔ رنگ مقابل، در شرح منبع'] ],
 'دیوارهٔ چربی‌دار: ورود سخت‌تر و خروج سخت‌تر رنگ.',
 [('اسیدفست‌بودن چه معنایی دارد؟','مقاومت در برابر از دست دادن رنگ پس از رنگ‌بری اسیدی است؛ ساختار چربی‌دار دیواره با آن مرتبط است.',['رنگ','رنگ‌بری','دیواره']),('دیواره چگونه به بقا کمک می‌کند؟','نفوذ کم و ترکیبات مؤثر بر فاگوسیت، مواجهه با عوامل محیطی و دفاع میزبان را تغییر می‌دهند؛ LAM در مهار ادغام فاگولیزوزومی مطرح است.',['نفوذ','فاگوسیت','LAM'])],warning=('تعمیم مقاومت','بی‌اثر بودن کلی الکل و آب‌ژاول، رتبهٔ ثابت مقاومت بعد از اسپور و نسبت‌دادن همهٔ ویژگی‌ها فقط به ضخامت دیواره، تعمیم‌های منبع‌اند؛ به دستور ضدعفونی تبدیل نشده‌اند.'))
A(1,'انتقال، ماکروفاژ و گرانولوم سل',[4,5,6,7], 'گرانولوم برای مهار است، اما التهاب می‌تواند بافت را نیز آسیب بزند.',[
 ['عامل و گروه','توبرکلوزیس شاخص مجموعهٔ سل؛ بوویس با سل گاوی و سابقهٔ لبنیات آلوده مطرح است. NTM گروه دیگرِ جزوه است.'],['انتقال','برای توبرکلوزیس، انتقال هوابرد از انسان و رسیدن ذرات به آلوئول؛ طول تماس، فضای بسته، تهویه و بار عامل در خطر مؤثرند.'],['بقای آغازین','ماکروفاژ آلوئولی عامل را می‌بلعد؛ اختلال اسیدی‌شدن و ادغام با لیزوزوم در متن مطرح است.'],['پاسخ اختصاصی','ارائهٔ آنتی‌ژن در غدهٔ لنفی، سلول T، اینترفرون گاما و فعال‌سازی ماکروفاژ؛ جذب سلول بیشتر و گرانولوم'],['بافت','سلول اپیتلوئید و غول‌پیکر لانگهانس، حلقهٔ سلول‌های ایمنی و امکان نکروز مرکزی؛ شکل‌های صفحات ۶ و ۷ همین سازمان و پیام‌رسانی را نشان می‌دهند.'],['یادآوری ایمنی','B و پلاسماسل پادتن می‌سازند؛ برای فهم مهار سل در این متن، محور T و فعال‌سازی ماکروفاژ برجسته‌تر است.'] ],
 'بلع، بقا، ارائه، T و اینترفرون، فعال‌سازی و محصورسازی.',
 [('گرانولوم چگونه شکل می‌گیرد؟','ارائهٔ آنتی‌ژن و پاسخ T با IFN-γ ماکروفاژ را فعال می‌کنند؛ تجمع سازمان‌یافتهٔ سلول‌ها عامل را محصور می‌کند و در عین مهار، التهاب می‌تواند آسیب بدهد.',['ارائه','T','IFN-γ','دو پیامد']),('چه عواملی خطر انتقال را تغییر می‌دهند؟','میزان و مدت مواجهه، بار میکروبی و محیط بسته با تهویهٔ کمتر در متن مطرح‌اند؛ ضعف ایمنی خطر پیشرفت بیماری را نیز بالا می‌برد.',['مواجهه','محیط','دفاع'])],warning=('سلول و جمعیت فرضی','سلول لانگهانس را نشانهٔ کاملاً اختصاصی یک عامل ندان. نسبت ۵٪ و ۹۵٪ در صفحهٔ ۶ یک جمعیت فرضی است و برابرکردن مستقیم ضعف ایمنی با همهٔ موارد فعال، ساده‌سازی است.'))
A(1,'نهفتگی، فعال‌شدن مجدد و آسیب ریه',[6,7,8], 'مهارشدن عامل با پاک‌شدن آن یکسان نیست.',[
 ['سه سرانجام','پاک‌سازی، مهار و نهفتگی، یا پیشرفت فعال در روایت درس'],['نهفتگی','عامل زنده و کم‌تکثیر با نبود نشانهٔ بیماری فعال؛ امکان ماندگاری طولانی'],['فعال‌شدن مجدد','ضعف ایمنی یا تغییر شرایط، ناپایداری ضایعه و امکان گسترش'],['آسیب','نکروز پنیری، حفره و فیبروز؛ اسکار جایگزین بافت سالمِ ازدست‌رفته می‌شود.'],['دو الگوی ضایعه','Exudative: الگوی التهابی/ترشحی شرح آغازین؛ Productive: سازمان گرانولوماتوز و محصورشدن در متن'],['نشانه‌ها','خستگی، تب کم‌درجه، تعریق شبانه؛ در ریه سرفه و خلط با امکان خون'] ],
 'مهار، پاک‌سازی نیست؛ کنترل کمتر، فعالیت بیشتر؛ آسیب می‌تواند اسکار بگذارد.',
 [('نهفتگی را با بیماری فعال مقایسه کنید.','نهفتگی در متن مهار عامل زنده بدون نشانهٔ فعال است؛ در بیماری فعال تکثیر، التهاب و تظاهر بالینی/ضایعهٔ فعال مطرح است. نهفتگی ممکن است دوباره فعال شود.',['عامل زنده','نشانه','مهار','بازفعال‌شدن']),('نقش دوگانهٔ ایمنی چیست؟','فعال‌سازی و گرانولوم عامل را مهار می‌کنند، اما پاسخ پایدار و شدید می‌تواند نکروز، فیبروز و اختلال عملکرد بسازد.',['مهار','التهاب','آسیب'])],warning=('تصویر و نام ارزنی','رد یا اثبات قطعی فعالیت صرفاً از عکس، طبیعی‌بودن همیشگی تصویر نهفتگی و نسبت‌دادن نام سل ارزنی به دانه‌های پوست در منبع نیازمند بررسی‌اند؛ الگوی منتشر را با یک ضایعهٔ پوستی الزامی یکی نکن.'))
A(1,'سل خارج‌ریوی و اهمیت دهان',[8,9,10], 'محل درگیری، علامت اختصاصی را تعیین می‌کند؛ بخش دهان در جزوه تأکید امتحانی دارد.',[
 ['مسیرهای برجستهٔ منبع','بلع خلط برای ورود گوارشی؛ جابه‌جایی سلول آلوده و گسترش لنفی/خونی برای محل‌های دیگر'],['گوارش، کبد، طحال و پانکراس','التهاب گرانولوماتوز و امکان اشتباه با توده؛ تشبیه بافتی، تشخیص قطعی نیست.'],['مننژ و پریکارد','درگیری عصبی به‌ویژه نوزاد و زمینهٔ نقص ایمنی؛ پردهٔ قلب در مثال دیگر'],['استخوان و چشم','ستون فقرات و لگن و تغییر شکل؛ چشم نیز در فهرست آمده است.'],['دهان؛ تأکید استاد','زبان محل برجسته؛ لثه، کام و لب هم ممکن‌اند. ضایعهٔ دردناک با حاشیهٔ قرمز و توصیف ماهواره‌ای/گرانولوماتوز در منبع'],['ادراری–تناسلی','گسترش از محل اولیه، درگیری کلیه و دستگاه تناسلی، پیامد ناباروری و آسیب مجاری'],['سایر شکل‌ها','منتشر/ارزنی، پستان و مادرزادی در فهرست؛ محل‌های مختلف الزاماً همزمان نیستند.'] ],
 'علامت عمومی مشترک؛ محل، علامت ویژه؛ در دهان، زبان را فراموش نکن.',
 [('دو مسیر مطرح برای خارج‌ریوی‌شدن چیست؟','بلع خلط برای مسیر گوارشی، و انتشار عامل با سلول‌های آلوده/راه لنفی و خونی برای درگیری سایر اندام‌ها.',['گوارشی','انتشار','محل']),('سل دهانی در جزوه چه ویژگی دارد؟','می‌تواند با یا بدون درگیری ریوی مطرح شود؛ زبان برجسته و لثه، کام و لب نیز در فهرست‌اند. درد، حاشیهٔ قرمز و نمای گرانولوماتوز از توصیف‌ها هستند.',['زبان','محل‌های دیگر','تظاهر'])],warning=('بارداری و تعمیم عددها','نفی انتقال جنینی سل در صفحهٔ ۱۰، یکی‌گرفتن اسیدفست با مقاومت به اسید معده، و درصدهای قطعی باروری/درمان در صفحهٔ ۹ نیازمند بررسی‌اند؛ این ادعاها بی‌صدا اصلاح نشده‌اند.'))
A(2,'تشخیص سل و محدودیت PPD',[10,11], 'دیدن باسیل، شناسایی گونه و سنجش پاسخ ایمنی سه پرسش متفاوت‌اند.',[
 ['اسمیر اسیدفست','سرنخ سریعِ حضور باسیل اسیدفست؛ به تنهایی همهٔ NTMها را از مجموعهٔ سل جدا نمی‌کند.'],['شناسایی و بررسی حساسیت','برای افتراق گونه و شناخت مقاومت مهم‌اند؛ نتیجهٔ دیرتر را با بی‌ارزش‌بودن یکی نکن. نام محیط لوونشتاین–جنسن و کلنی زبر در صفحهٔ ۴، سرنخ تصویری/توصیفی است.'],['PPD','آنتی‌ژن پروتئینی و پاسخ تأخیریِ وابسته به سلول T و حافظه؛ سفتی با قرمزی یکی نیست.'],['تفسیر','پاسخ، حساسیت ایمنی را نشان می‌دهد؛ متن در ادامه تصریح می‌کند فعال و نهفته را جدا نمی‌کند.'],['منفی کاذب','نقص ایمنی، بیماری شدید، سن بسیار کم/بالا و سوءتغذیه از مثال‌های منبع'] ],
 'باسیل، گونه، پاسخ ایمنی؛ PPD پاسخ است، تشخیص فعالیت نیست.',
 [('چرا PPD مثبت فعالیت سل را ثابت نمی‌کند؟','حافظه و واکنش ایمنی سلولی به آنتی‌ژن را می‌سنجد؛ در نهفته و فعال می‌تواند مثبت باشد و در ضعف ایمنی حتی با بیماری منفی شود.',['حافظه','فعال/نهفته','منفی کاذب']),('چرا اسمیر و شناسایی گونه نقش یکسان ندارند؟','اسیدفست‌بودن یک گروه را نشان می‌دهد؛ افتراق گونه و مقاومت به اطلاعات اختصاصی‌تری نیاز دارد.',['گروه','گونه','مقاومت'])],warning=('تناقض PPD','سه‌گانهٔ اندازهٔ سفتی در صفحهٔ ۱۰ ابتدا فعال/نهفته را نتیجه می‌گیرد، اما پایان همان صفحه و صفحهٔ ۱۱ این افتراق را رد می‌کنند. زمان خواندن در استخراج هم وارونه است؛ این راهنما دستور اجرا یا حد عددی تشخیص از آن نمی‌سازد.'))
A(2,'واکسن، درمان ترکیبی و مقاومت سل',[11,12,13], 'تأکید استاد بر نام‌های خط اول، تعریف مقاومت و منطق پیگیری درمان است.',[
 ['BCG','واکسن زندهٔ تضعیف‌شده مرتبط با بوویس در روایت درس؛ نقش محافظتی علیه شکل‌های شدید کودکی برجسته است.'],['نام‌های خط اولِ جزوه','ایزونیازید، ریفامپین، اتامبوتول، پیرازینامید و استرپتومایسین؛ فهرست منبع، نه رژیم به‌روز'],['تک‌دارویی و چنددارویی','مقاومت به یک دارو؛ یا به بیش از یکی بدون مقاومت همزمان به ایزونیازید و ریفامپین در تعریف Poly-drug منبع'],['MDR','مقاومت همزمان به ایزونیازید و ریفامپین'],['XDR و TDR','منبع XDR را با MDR و مقاومت بیشتر به خط دوم توضیح می‌دهد؛ تعریف دقیق و جایگاه رسمی TDR نیاز به بررسی دارد.'],['DOT','پیگیری و مشاهدهٔ دریافت درمان برای کاهش رهاکردن و شکست؛ علت مطالعه، پایبندی است.'],['HIV؛ تأکید استاد','کاهش ایمنی سلولی، افزایش خطر پیشرفت و شکل‌های خارج‌ریوی؛ خود جزوه می‌گوید اعداد لازم نیست حفظ شوند.'] ],
 'دو داروی کلیدی برای تعریف MDR؛ چنددارویی و پیگیری برای محدودکردن انتخاب مقاومت.',
 [('MDR با Poly-drug چه تفاوتی دارد؟','در تعریف جزوه، MDR شامل مقاومت همزمان به ایزونیازید و ریفامپین است؛ Poly-drug بیش از یک دارو را دارد ولی این جفتِ همزمان را ندارد.',['جفت کلیدی','تعداد کافی نیست']),('DOT و درمان ترکیبی چه هدف مفهومی دارند؟','درمان ترکیبی احتمال باقی‌ماندن جمعیت مقاوم را محدود می‌کند؛ پیگیری، دریافت کامل درمان و کاهش رهاکردن را هدف دارد.',['جمعیت مقاوم','پایبندی','رهاکردن'])],more=P('نام‌های خط دوم در منبع آمده‌اند، ولی استاد حفظ آن‌ها را لازم ندانسته: آمینوگلیکوزیدها، فلوروکینولون‌ها، پلی‌پپتیدِ با نام مبهم پاتئومایسین، سیکلوسرین، اتیونامید و PAS. مدت‌ها و ترکیب‌ها در این راهنما به دستور درمان تبدیل نشده‌اند.'),warning=('تاریخچه، دارو و تعریف','تاریخچهٔ BCG، عدد پاساژ و محافظت نزدیک به صددرصد، اثر هر دو داروی کلیدی بر دیواره، تکرار استرپتومایسین در دو خط، تعریف XDR و ادعای ایجاد مستقیم جهش به دست دارو نیازمند بررسی‌اند. تمایز پیدایش تغییر و انتخاب جمعیت مقاوم را حفظ کن.'))
A(3,'مایکوباکتری‌های غیرسلی: دو محور طبقه‌بندی',[15,16], 'محیطی‌بودن و فرصت‌طلبی را با ظاهر اسیدفست اشتباه نگیر.',[
 ['نام‌ها','NTM، آتیپیک، محیطی و فرصت‌طلب در متن؛ عمدتاً آب/خاک و انتقال از محیط، با عدم انتقال معمول فردبه‌فرد در روایت منبع'],['زمینه','ضعف ایمنی، HIV، پیوند، دیالیز و سرکوب ایمنی؛ اهمیت تشخیص گونه نسبت به گزارش کلی اسیدفست'],['سرعت','سریع: فورتوئیتوم، کلونئی و آبسسوس؛ کند: گروه‌های دیگر. سرعت یک ویژگی رده‌بندی است، نه شدت بیماری.'],['فتوکروموژن','رنگدانه در نور؛ کانزاسی'],['اسکوتوکروموژن','رنگدانه حتی در تاریکی؛ اسکروفولاسئوم'],['غیرکروموژن','بدون رنگدانه؛ MAC در فهرست'] ],
 'سرعت یک محور؛ نور و رنگدانه محور دیگر.',
 [('سه گروه رنگدانه را با مثال بنویسید.','فتوکروموژن در نور مانند کانزاسی؛ اسکوتوکروموژن در تاریکی هم مانند اسکروفولاسئوم؛ غیرکروموژن مانند MAC.',['نور','تاریکی','بی‌رنگ','مثال']),('چرا اسیدفست مثبت برابر سل نیست؟','گروه‌های غیرسلی هم اسیدفست‌اند و تظاهر مشابه می‌دهند؛ هویت و زمینه برای افتراق مهم‌اند.',['NTM','شباهت','افتراق'])],warning=('طبقه‌بندی و ژنتیک لپره','صفحهٔ ۱۵ ناتوانی کشت لپره را دلیل نبود بررسی ژنتیکی کامل می‌داند؛ این استنتاج از متن ثابت نیست. درصد بیماری‌زایی و تعمیم مقاومت به کلر هم بدون قید آمده‌اند.'))
A(3,'NTM: ریه، لنف، پوست و انتشار',[17,18,19,20], 'چهار تابلوی بالینی را با یک یا دو عامل شاخص به خاطر بسپار.',[
 ['ریه','کانزاسی، MAC، آبسسوس و زنوپی؛ زمینهٔ بیماری مزمن ریه، COPD، برونشکتازی و سیستیک‌فیبروزیس، با امکان بیماری در فرد فاقد همان زمینه‌ها'],['غدد لنفی','کودک کم‌سن، اغلب یک‌طرفه و زیر فک؛ اسکروفولاسئوم و MAC؛ گرانولوم و گاه مسیر تخلیه'],['پوست و بافت نرم','پس از آسیب/جسم خارجی: فورتوئیتوم، کلونئی، آبسسوس و MAC؛ مارینوم با تماس محیط آبی و گرانولوم آکواریوم'],['اولسرانس','زخم بورولی و تخریب پوست و بافت؛ گونهٔ جدا از مارینوم'],['منتشر','به‌ویژه با کاهش CD4 و ضعف ایمنی؛ MAC، کانزاسی، آبسسوس و کلونئی؛ تب، اسهال و کاهش وزن'],['درمان در متن','گونه و حساسیت مهم‌اند؛ ماکرولید، ریفامپین و اتامبوتول برای بعضی گروه‌ها، داکسی‌سایکلین/آمیکاسین برای برخی سریع‌رشدها نام برده شده‌اند.'] ],
 'ریه، لنف، پوست، انتشار؛ آکواریوم مارینوم، بورولی اولسرانس.',
 [('مارینوم و اولسرانس چه تفاوت شاخصی دارند؟','مارینوم در متن با محیط آبی و گرانولوم آکواریوم، اغلب دست، مرتبط است؛ اولسرانس با زخم بورولی و آسیب مخرب‌تر معرفی شده است.',['محیط','دو ضایعه','دو نام']),('چهار تابلوی NTM را نام ببرید.','بیماری ریوی، لنفادنیت، پوست/بافت نرم و شکل منتشر؛ برای هر کدام عامل و زمینه را اضافه می‌کنم.',['چهار گروه','عامل','زمینه'])],warning=('تعمیم درمان و پیش‌آگهی','کم‌اهمیت‌بودن همیشگی MAC در سالم، نبود زمینه در بیماری منتشر، پیش‌آگهی قدیمی سیستیک‌فیبروزیس، حفاظت کلی BCG و ترکیب/مدت واحد درمان در این بخش نیاز به بررسی دارند؛ فهرست داروها راهنمای تجویز نیست.'))
A(3,'جذام: ایمنی، عصب و دو قطب بیماری',[20,21,22,23], 'در جذام، بار باکتری و نوع پاسخ سلولی کنار هم معنای ضایعه را روشن می‌کنند.',[
 ['عامل و بافت','لپره؛ در متن فاقد کشت معمول؛ گرایش به ناحیه‌های خنک‌تر مانند گوش، بینی، انگشت و اعصاب محیطی سطحی'],['تماس','تماس نزدیک و طولانی و مسیر تنفسی در ادامهٔ متن برجسته است؛ مواجهه الزاماً بیماری نیست.'],['توبرکولوئید','پاسخ سلولی مؤثر، گرانولوم منظم، باکتری کم و ضایعهٔ محدودتر با حاشیهٔ مشخص؛ آسیب عصب و بی‌حسی می‌تواند زخم ثانویه بسازد.'],['لپروماتوز','پاسخ سلولی ضعیف‌تر، ماکروفاژ کف‌آلود پرمیکروب، ضایعات متعدد متقارن و حاشیهٔ نامشخص؛ حس ممکن است ابتدا حفظ و دیرتر مختل شود.'],['بوردِرلاین','طیف میان دو قطب'],['تظاهر لپروماتوز','ندول، ضخیم‌شدن صورت و نمای شیرمانند، ریزش ابرو/مژه، مخاط بینی و دهان، اختلال عصب و تغییر شکل اندام'],['لپرومین','سنجش پاسخ سلولی، نه اثبات قطعی عفونت؛ پاسخ دیررس در توبرکولوئید و ضعف پاسخ در لپروماتوز در متن'],['ENL','آنتی‌ژن فراوان، کمپلکس ایمنی، فعال‌شدن التهاب و آسیب؛ در زمینهٔ بار بالا یا تغییرات حین درمان شرح داده شده است.'] ],
 'توبرکولوئید: سلول قوی و باسیل کم؛ لپروماتوز: سلول ضعیف‌تر و باسیل بیشتر.',
 [('دو قطب جذام را در چهار محور مقایسه کنید.','توبرکولوئید با پاسخ سلولی بهتر، بار کمتر، گرانولوم منظم و ضایعهٔ محدودتر همراه است؛ لپروماتوز با پاسخ ضعیف‌تر، بار زیاد، ماکروفاژ کف‌آلود و ضایعات متقارن گسترده. هر دو می‌توانند عصب را آسیب بزنند.',['ایمنی','بار','بافت','ضایعه','عصب']),('لپرومین و ENL چه پدیده‌های متفاوتی‌اند؟','لپرومین سنجش پاسخ سلولی به آنتی‌ژن است؛ ENL در متن التهاب مرتبط با کمپلکس ایمنی و بار آنتی‌ژنی بالاست.',['سنجش سلولی','کمپلکس ایمنی','التهاب'])],more=P('داپسون/DDS و درمان چنددارویی در متن نام برده شده‌اند. دوره‌های ده‌ساله یا مادام‌العمر به روایت گذشته مربوط‌اند؛ بازسازی بافت آسیب‌دیده با حذف میکروب یکسان نیست.'),warning=('قیدهای جذام','عدم قطعیت راه انتقال در ابتدا و قطعیت بعدی، ادعای تصادفی‌بودن کامل عملکرد ایمنی و «متعددتر» بودن ضایعات توبرکولوئید با توصیف دو قطب سازگار نیستند. اعداد زمان پاسخ لپرومین در استخراج وارونه‌اند؛ دستور اجرا از آن‌ها ساخته نشده است.'))
A(4,'اسپیروکت: شکل، اندوفلاژل و نام‌ها',[25,26,27], 'نازک‌بودن و جای تاژک داخلی، دو ویژگی مهم برای خواندن شکل‌ها هستند.',[
 ['ساختار','اسپیروکت با پوشش شبیه گرم منفی، غشای داخلی و خارجی و پپتیدوگلیکان نازک؛ تقسیم دوتایی'],['اندوفلاژل','فیلامان محوری در فضای پیرامونی، نه تاژک آزاد بیرونی؛ حرکت پیچشی و کمک به نفوذ'],['مقایسهٔ قطر','بورلیا ضخیم‌تر، ترپونما حد واسط، لپتوسپیرا باریک‌تر در تصویر'],['مشاهده','گرم معمول کافی نیست؛ زمینهٔ تاریک، نقره و فلورسانس نام برده شده‌اند؛ قابلیت روش‌ها برای همهٔ جنس‌ها یکسان فرض نشود.'],['ترپونما','پالیدوم، پرتنوئه، اندمیکوم و کاراتئوم؛ سه نام اول در چارچوب زیرگونه‌های پالیدوم هم آمده‌اند.'],['بورلیا','رکورنتیس: تب راجعه؛ هرمسی: تب راجعهٔ اندمیک؛ بورگدورفری: لایم'] ],
 'تاژک درون پوشش، حرکت پیچشی؛ سه جنس را با قطر و بیماری به هم وصل کن.',
 [('اندوفلاژل چه تفاوتی با تاژک سطحی دارد؟','داخل فضای پیرامونی و زیر پوشش بیرونی قرار دارد و با پیچش، حرکت خاص اسپیروکت را ایجاد می‌کند.',['جایگاه','پوشش','پیچش']),('سه جنس مهم و بیماری شاخص را نام ببرید.','ترپونما با سیفلیس و ترپونماتوزها؛ بورلیا با تب راجعه و لایم؛ لپتوسپیرا با لپتوسپیروز.',['سه جنس','سه محور بیماری'])],warning=('نام و تعمیم اکسیژن','نام Treponema intercalatum، اختصاصی دانستن گلیکوزآمینوگلیکانِ دیواره، میکروآئروفیل دانستن همهٔ گروه‌ها و ادعای تاریخی نبود مطلق کشت پالیدوم نیازمند بررسی‌اند.'))
A(4,'سیفلیس: عامل، انتقال و توالی بیماری',[27,28,29], 'بهبود ضایعه را برابر پاک‌شدن عفونت ندان.',[
 ['عامل','ترپونما پالیدوم، نازک و حساس به خشکی؛ رشد کند در شرح منبع'],['عوامل مطرح','پروتئین سطحی برای اتصال، پوشش فیبرونکتین برای فرار از شناخت و هیالورونیداز برای انتشار بافتی در روایت جزوه'],['انتقال','تماس جنسی و تماس با ضایعه، انتقال جفتی و خون در فهرست؛ مخاط یا سد آسیب‌دیده محل ورود مطرح‌اند.'],['اولیه','شانکر معمولاً سفت و بی‌درد در محل ورود، با غدهٔ لنفی نزدیک؛ امکان بهبود ظاهری'],['ثانویه','انتشار، راش پوستی، پچ مخاطی و کوندیلوماتا؛ ضایعات دهان هم مطرح‌اند.'],['نهفتگی','نبود ضایعهٔ آشکار با باقی‌ماندن شواهد سرولوژیک؛ رفع علامت، اثبات حذف نیست.'],['دیررس','گوماتا، درگیری قلبی–عروقی و عصبی در فهرست؛ این‌ها نباید به شکل یک مسیر الزامی در همه نوشته شوند.'],['مادرزادی','انتقال جفتی؛ زودرس با درگیری عمومی/کبد و طحال و استخوان، دیررس با قرنیه، شنوایی و تغییر استخوان در متن'] ],
 'محل ورود، انتشار، بی‌علامتی، آسیب دیررس؛ بهبود ظاهری با درمان یکی نیست.',
 [('اولیه و ثانویه را مقایسه کنید.','اولیه ضایعهٔ موضعی شانکر و غدهٔ نزدیک دارد؛ ثانویه انتشار با راش و ضایعات مخاطی و کوندیلوماتا.',['محل','شکل','انتشار']),('چرا رفع علامت پایان استدلال نیست؟','عامل می‌تواند با نبود ضایعه وارد نهفتگی شود؛ پاسخ پادتنی و خطر تظاهر بعدی باید از بهبود ظاهری جدا شوند.',['نهفتگی','سرولوژی','ظاهر'])],warning=('بافت و سرولوژی','خودایمنیِ صرف دانستن مرحلهٔ سوم، اثبات حضور آنتی‌ژن فقط از پادتن پایدار، نفی عبور همهٔ میکروب‌ها از پوست سالم و بی‌خطر دانستن همیشگی شکل دیررس مادرزادی، تعمیم‌های نیازمند بررسی‌اند.'))
A(4,'سیفلیس: منطق آزمون‌ها و پیگیری',[30,31,32], 'آزمون پادتن را با دیدن خود عامل اشتباه نگیر؛ هدف هر گروه متفاوت است.',[
 ['مستقیم','مشاهدهٔ عامل در ضایعه با روش متناسب؛ نتیجه وابسته به محل و مرحله است.'],['غیرترپونمی','آنتی‌ژن غیر اختصاصی، مانند چربی مرتبط با قلب در روایت متن؛ VDRL، امکان مثبت کاذب و کاربرد پیگیری'],['ترپونمی','آنتی‌ژن اختصاصی‌تر؛ TPI بر بی‌حرکت‌شدن، FTA-ABS بر اتصال پادتن و فلورسانس، TPHA بر تجمع ذرات پوشیده از آنتی‌ژن استوار معرفی شده‌اند.'],['اختصاصی گروه','آنتی‌ژن ترپونمای رایتر در دسته‌بندی متن'],['مثبت کاذب','برای غیرترپونمی: بارداری، هپاتیت، تب راجعه، جذام، مونونوکلئوز و مصرف تزریقی مواد از مثال‌های جزوه'],['عصبی','بررسی CSF و VDRL در بحث منبع؛ نتیجهٔ هر آزمون تنها محور تصمیم نیست.'],['درمان/پیشگیری','پنی‌سیلین در جزوه برجسته؛ نبود واکسن و کنترل مواجهه ذکر شده‌اند. همزمانی HIV نیازمند توجه به زمینه است.'] ],
 'غیرترپونمی: غیر اختصاصی و پیگیری؛ ترپونمی: شناسایی اختصاصی‌تر.',
 [('دو گروه سرولوژی چه تفاوتی دارند؟','گروه غیرترپونمی آنتی‌ژن غیر اختصاصی‌تر و امکان مثبت کاذب بیشتری دارد و برای پیگیری مطرح است؛ ترپونمی بر آنتی‌ژن مرتبط با عامل تکیه دارد. هیچ نتیجه را بدون زمینه برابر فعالیت قطعی نمی‌گیرم.',['آنتی‌ژن','مثبت کاذب','پیگیری','زمینه']),('اصل FTA-ABS و TPHA را مقایسه کنید.','اولی پاسخ پادتنی را با نشانهٔ فلورسانس و دومی با تجمع ذراتِ حامل آنتی‌ژن نشان می‌دهد؛ هر دو از دیدن مستقیم عامل در ضایعه جدا هستند.',['فلورسانس','تجمع','پادتن'])],warning=('محدودیت آزمون‌ها','مثبت کاذبِ ترپونمی «فقط در لایم»، بی‌اعتباری کلی سرولوژی در HIV و هم‌ارزی همهٔ آزمون‌ها در پایش، از منبع قابل تعمیم نیست. نام تاریخی TPI و ادعای حساسیت یکسان در همهٔ مراحل نیز با قید خوانده شوند.'))
A(4,'ترپونماتوزهای غیرجنسی',[29,30,32,33,34], 'همهٔ ضایعات ترپونمی جنسی نیستند؛ محل، سن و پیامد را مقایسه کن.',[
 ['یاز','پرتنوئه؛ تماس مستقیم؛ ضایعات پاپیلومامانند دست و پا، سپس ماکول/پاپول و عود؛ گوماتا و آسیب دیررس در فهرست'],['اندمیک','اندمیکوم؛ تماس نزدیک غیرجنسی، کودک و دهان در متن؛ مرحلهٔ بعد ضایعات مخاطی و در ادامه آسیب گوماتوز حلق/استخوان'],['پینتا','کاراتئوم؛ تماس مستقیم، پوست سطحی دست و پا؛ تغییر رنگ پررنگ/کم‌رنگ و تخریب کمتر'],['مقایسه با سیفلیس','شانکر اولیه و کوندیلومای ثانویه را به همهٔ این سه بیماری تعمیم نده؛ جدول مقایسهٔ منبع محور محل و شدت دارد.'] ],
 'یاز: ضایعه و تخریب؛ اندمیک: دهان؛ پینتا: رنگ پوست.',
 [('سه ترپونماتوز را مقایسه کنید.','یاز با پرتنوئه و ضایعات پوستی/آسیب، اندمیک با اندمیکوم و درگیری دهان، پینتا با کاراتئوم و تغییر رنگ کم‌تخریب‌تر در متن مطرح‌اند؛ راه مشترک، تماس مستقیم غیرجنسی است.',['عامل','محل','شدت','راه']),('سن یاز در منبع چه ابهامی دارد؟','صفحهٔ ۳۳ ابتدا بالغ را برجسته می‌کند و در همان مقایسه کودک را؛ این تفاوت باید به عنوان تناقض بررسی شود.',['دو ادعا','عدم انتخاب بی‌صدا'])],warning=('تناقض سن','یاز در یک بند بیشتر در بالغ و در مقایسهٔ بعدی بیشتر در کودک معرفی شده است. همچنین شدت مراحل را به عنوان توصیف منبع بخوان، نه الگوی اجباری هر مورد.'))
A(4,'بورلیا: عود، لایم و ضایعهٔ دهان',[34,35], 'در تب راجعه، تغییر آنتی‌ژن علت تکرار پاسخ و عود در روایت درس است.',[
 ['تب راجعهٔ اپیدمیک','رکورنتیس و شپش؛ تب، سردرد و درد عضلانی، پاسخ پادتنی و کاهش علائم، سپس بازگشت جمعیت متفاوت'],['تب راجعهٔ اندمیک','هرمسی و ناقل کنه در متن؛ نگارش نام در صفحهٔ ۳۴ مبهم است.'],['فرار آنتی‌ژنی','تغییر آنتی‌ژن سطحی، کاهش کارایی پادتن قبلی و تکثیر دوباره؛ چرخهٔ تکرار تب'],['بورگدورفری','لایم با کنه و اریتم مهاجرِ در حال گسترش؛ سپس درگیری مفصل و عصبی در شرح منبع'],['وینسنتی','نام تاریخیِ مطرح در فلور دهان و همراهی با باسیل دوکی بی‌هوازی؛ سوءتغذیه و بهداشت نامناسب، نکروز لثه و آنژین ونسان در متن'],['تشخیص و درمان در جزوه','در تب راجعه مشاهدهٔ خون، در لایم نقش سرولوژی؛ پنی‌سیلین/مترونیدازول برای دو جزء بحث دهانی و آموکسی‌سیلین برای لایم نام برده شده‌اند.'] ],
 'آنتی‌ژن تازه، پادتن قبلی کمتر مؤثر، جمعیت دوباره و تب دوباره.',
 [('عود تب چگونه توضیح داده می‌شود؟','پاسخ پادتنی جمعیت غالب را کم می‌کند؛ جمعیت با آنتی‌ژن متفاوت باقی می‌ماند و گسترش می‌یابد، پس تب برمی‌گردد.',['انتخاب جمعیت','آنتی‌ژن','پادتن','عود']),('لایم و بحث ونسان چه تفاوتی دارند؟','لایم با کنه، بورگدورفری و اریتم مهاجر مطرح است؛ ونسان در متن به اجتماع دهانی اسپیروکت و باسیل دوکی با زمینهٔ نامناسب مربوط است.',['عامل','راه','محل'])],warning=('نام و ناقل','نگارش Borrelia gutunumi hermsii، نام تاریخی وینسنتی، یکی‌گرفتن نکروز لثه و التهاب حلق، تعمیم «نبود هر مقاومت دارویی» و مخزن حیوانی برای همهٔ شکل‌ها نیاز به بررسی دارند.'))
A(4,'لپتوسپیرا و سندرم ویل',[35,36], 'عامل محیطی–حیوانی را از بیماری با ناقل حشره جدا کن.',[
 ['عامل','لپتوسپیرا اینتروگانس، بسیار باریک و متحرک؛ روش معمول گرم برای مشاهده مناسب نیست.'],['انتقال','حیوان مخزن و انسان میزبان تصادفی؛ تماس مخاط یا پوست آسیب‌دیده با محیط آلوده، با نقش ادرار حیوان در متن'],['خفیف','تب، سردرد و درد عضلانی؛ امکان بی‌علامتی'],['ویل','شکل شدید با درگیری کبد و یرقان، کلیه و ادرار خونی و امکان مننژیت'],['نام سرووار','Icterohaemorrhagiae در بحث شدت آمده است.'],['تشخیص/پیشگیری','خون، ادرار یا CSF بسته به زمینه و سرولوژی در متن؛ کنترل تماس و مخزن و پوشش محافظ نام برده شده‌اند. پنی‌سیلین در فهرست درمان است.'] ],
 'حیوان و محیط؛ کبد و کلیه در ویل؛ ناقل حشره محور این بحث نیست.',
 [('ویل چه تفاوتی با شکل خفیف دارد؟','شکل خفیف بیشتر علائم عمومی دارد؛ ویل با اختلال شدید اندام، به‌ویژه کبد و کلیه و گاه دستگاه عصبی، مطرح است.',['عمومی','اندام','شدت']),('انتقال لپتوسپیرا با بورلیا چه تفاوتی دارد؟','در این متن لپتوسپیرا با تماس محیطی مرتبط با حیوان و راه مخاط/پوست آسیب‌دیده است؛ بسیاری از بورلیاهای مورد بحث ناقل شپش یا کنه دارند.',['محیط','حیوان','ناقل'])],warning=('دامنهٔ مخزن و دفع','مدفوع و «دام‌ها مخزن اصلی همهٔ موارد» در متن بدون تفکیک آمده‌اند؛ از آن‌ها یک مسیر غالب ثابت برای همه نتیجه نگیر. عبارت داروی ساده «کافی است» نیز برنامهٔ یکسان برای هر شدت نیست.'))
mixed=[Q('چرا ایمنی سلولی در سل و جذام محور مشترک است؟','فعال‌سازی ماکروفاژ و محصورسازی به مهار کمک می‌کند؛ ضعف آن، بقا و انتشار را افزایش می‌دهد. پاسخ التهابی در هر دو می‌تواند همزمان آسیب ایجاد کند.',['T/ماکروفاژ','مهار','آسیب'],[5,7,21,22]),Q('PPD، لپرومین و سرولوژی سیفلیس را از نظر چیزی که می‌سنجند مقایسه کنید.','دو آزمون نخست به پاسخ سلولی مرتبط‌اند؛ سرولوژی سیفلیس پادتن را می‌سنجد. هیچ‌کدام به تنهایی تمام ابعاد فعالیت، گونه و آسیب را ثابت نمی‌کنند.',['سلولی','پادتن','محدودیت'],[10,11,22,31,32]),Q('سل، NTM، جذام و اسپیروکت‌ها را از نظر منشأ مقایسه کنید.','سل انسانی در این درس هوابرد؛ NTM عمدتاً محیطی؛ جذام تماس طولانی/تنفسی؛ سیفلیس تماس و جفت؛ بورلیا غالباً ناقل؛ لپتوسپیرا تماس محیطی حیوانی.',['شش مسیر','عامل متناسب'],[4,15,20,28,34,35]),Q('چرا درمان ناموفق را فقط به یک ویژگی باکتری نسبت نمی‌دهیم؟','گونه و مقاومت، محل درگیری، ایمنی و پایبندی همگی در متن‌ها مطرح‌اند؛ دیواره یا رشد کند تنها بخشی از توضیح‌اند.',['گونه','مقاومت','میزبان','پایبندی'],[3,12,13,17,20])]
